    total_edge_count = 0
    max_depth = 0
    for hops, _sort_key, source_key in other_entries:
        # 正向定序 BFS（同 etp）：邻接表各边 first 全局互异且按首
        # 次发生时刻升序，首次到达 target 的路径即跳数最少且沿途
        # first 序列字典序最小者，与同区间 etp(source,target) 逐
