            ety_side_json(path_node)
            for path_node in reversed_nodes
        ]
        path_edges = []
        for edge_key in reversed_edges:
            edge_kind, edge_before, edge_after = edge_key
            edge_count, edge_first, edge_last = edge_rows[edge_key]
