                {
                    "kind": edge_kind,
                    "before": ety_side_json(edge_before),
                    "after": ety_side_json(edge_after),
                    "count": edge_count,
                    "first": edge_first,
                    "last": edge_last,
                }
            )
        items.append(
            {
                "source": ety_side_json(source_key),
                "hops": hops,
                "nodes": path_nodes,
                "edges": path_edges,
            }
        )
        total_edge_count += hops
        if hops > max_depth:
            max_depth = hops
    results.append(
        {
            "op": "ety",
            "first": first,
            "last": last,
            "latest": latest,
            "truncated": truncated,
            "target": target_json,
            "max_hops": max_hops,
            "items": items,
            "summary": {
                "reachable": len(items),
                "depth": max_depth,
                "edges": total_edge_count,
            },
        }
