import sys, random, heapq
sys.path.insert(0,'.')
import test_balancer as tb
class T(tb.EpSwitchAuditTimeReachabilityTest): pass
t=T()
EP1=t.EP1; EP2=t.EP2
def key(side):
    return ("EMPTY",) if side["state"]=="EMPTY" else ("ACTIVE",side["digest"],side["at"])
def build(trial):
    rng=random.Random(trial)
    items1=[("a",None,EP1)]; items2=[("a",None,EP2)]
    ops=[{"op":"ci","config":tb.config_v11(1),"now":0}]
    cur=None; now=0
    for i in range(rng.randint(1,75)):
        now+=rng.randint(1,3)
        if cur is None:
            tgt=rng.choice([items1,items2]); at=rng.randint(0,10**6)
            ops.append(t.es(tgt,0,at,now)); cur=(t.switch_digest(tgt,0),at)
        else:
            if rng.random()<0.55:
                tgt=rng.choice([items1,items2]); at=rng.randint(0,10**6)
                nd=(t.switch_digest(tgt,0),at)
                if nd!=cur: ops.append(t.es(tgt,0,at,now)); cur=nd
            else:
                ops.append({"op":"eu","digest":cur[0],"at":cur[1],"now":now}); cur=None
    now+=1
    ops.append({"op":"add","id":"zfin","weight":100,"d":0,"now":now})
    return ops,now
for trial in range(120):
    ops,lc=build(trial)
    rng=random.Random(trial*99+7)
    f=rng.choice([0, rng.randint(0,max(lc-1,0))]); mh=rng.randint(0,64)
    etr=next(x for x in t.run_ops(ops+[{"op":"etr","first":f,"last":lc}]) if x["op"]=="etr")
    adj={}
    for e in etr["edges"]: adj.setdefault(key(e["before"]),[]).append((key(e["after"]),e["first"]))
    for v in adj.values(): v.sort(key=lambda z:z[1])
    nodes=set(adj)|{a for v in adj.values() for a,_ in v}
    def shortest(src,dst):
        if src==dst: return (0,())
        dist={src:(0,())}; pq=[((0,()),src)]
        while pq:
            (h,seq),u=heapq.heappop(pq)
            if dist.get(u)!=(h,seq): continue
            if u==dst: return (h,seq)
            for w,fst in adj.get(u,()):
                nd=(h+1,seq+(fst,))
                if nd<dist.get(w,(10**9,None)):
                    dist[w]=nd; heapq.heappush(pq,(nd,w))
        return None
    universe=list(nodes) or [("EMPTY",)]
    for tgt0 in rng.sample(universe, min(5,len(universe))):
        tgt=None if tgt0==("EMPTY",) else (tgt0[1],tgt0[2])
        r=next(x for x in t.run_ops(ops+[{"op":"ety","first":f,"last":lc,"target":t.side(tgt),"max_hops":mh}]) if x["op"]=="ety")
        exp=[]
        for s in nodes:
            if s==tgt0: continue
            res=shortest(s,tgt0)
            if res and res[0]<=mh:
                sk=(0,) if s==("EMPTY",) else (1,s[1].encode(),s[2])
                exp.append((res[0],sk,s))
        exp.sort(key=lambda z:(z[0],z[1]))
        got=[(it["hops"],(0,) if it["source"]["state"]=="EMPTY" else (1,it["source"]["digest"].encode(),it["source"]["at"]),key(it["source"])) for it in r["items"][1:]]
        assert exp==got,(trial,tgt)
        ds=[it["hops"] for it in r["items"]]
        assert r["summary"]=={"reachable":len(r["items"]),"depth":max(ds),"edges":sum(ds)}
        assert r["truncated"]==etr["truncated"] and r["latest"]==etr["latest"]
        assert r["items"][0]["source"]==t.side(tgt) and r["items"][0]["hops"]==0
        assert r["items"][0]["nodes"]==[t.side(tgt)] and r["items"][0]["edges"]==[]
        for it in r["items"][1:]:
            assert it["nodes"][0]==it["source"] and it["nodes"][-1]==t.side(tgt)
            assert len(it["nodes"])==it["hops"]+1
            for i,e in enumerate(it["edges"]):
                assert e["before"]==it["nodes"][i] and e["after"]==it["nodes"][i+1]
        for it in r["items"][1:3]:
            ep=next(x for x in t.run_ops(ops+[{"op":"etp","first":f,"last":lc,"source":it["source"],"target":t.side(tgt)}]) if x["op"]=="etp")
            assert ep["found"] and ep["hops"]==it["hops"]
            assert ep["nodes"]==it["nodes"] and ep["edges"]==it["edges"],trial
print("random cross-check OK (120 trials x 5 targets)")
